# BUG: uses 30 instead of 32
def celsius_to_fahrenheit(c: float) -> float:
    return c * 9 / 5 + 30


# BUG: wrong order of operations — should be (f - 32) * 5 / 9
def fahrenheit_to_celsius(f: float) -> float:
    return f * 5 / 9 - 32


# BUG: subtracts 273.15 instead of adding
def celsius_to_kelvin(c: float) -> float:
    return c - 273.15

from src.tempconv import celsius_to_fahrenheit, fahrenheit_to_celsius, celsius_to_kelvin


def test_c_to_f_freezing():
    assert abs(celsius_to_fahrenheit(0) - 32.0) < 1e-9


def test_c_to_f_boiling():
    assert abs(celsius_to_fahrenheit(100) - 212.0) < 1e-9


def test_f_to_c_freezing():
    assert abs(fahrenheit_to_celsius(32) - 0.0) < 1e-9


def test_f_to_c_boiling():
    assert abs(fahrenheit_to_celsius(212) - 100.0) < 1e-9


def test_c_to_kelvin():
    assert abs(celsius_to_kelvin(0) - 273.15) < 1e-9
